(() => {
  'use strict';
  const M=globalThis.StonestormEquipment,S=globalThis.StonestormEquipmentStorage,T=globalThis.StonestormEquipmentSwitch;
  let snapshot=null,config=globalThis.STONESTORM_EQUIPMENT_DATA?.config,configError='',revision=0;
  const subscribers=new Set(),labels=globalThis.STONESTORM_EQUIPMENT_DATA?.labels??{};
  const slotNames={weapon:'Fegyver',armor:'Páncél',helmet:'Sisak',shield:'Pajzs',boots:'Csizma',bracelet:'Karkötő',necklace:'Nyaklánc',earrings:'Fülbevaló'};
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let refreshState={state:'idle',code:''},lastAttempt=0,lastSuccess=null,timeout=null;
  const notify=(changed=true)=>{if(changed)revision++;for(const fn of subscribers)fn(changed);};
  const refreshLabels={'source-unavailable':'A játék igazolt kliensmodulja még nem érhető el. Várd meg a játék betöltését, majd próbáld újra.','source-changed':'A játék kliensmodulja megváltozott; új ellenőrzés szükséges.','no-character':'A GET-válaszban nincs karakteradat.','read-failed':'A karakter GET-kérése nem sikerült. Ellenőrizd, hogy a játékban be vagy-e jelentkezve.','cooldown':'Várj néhány másodpercet az újraolvasás előtt.','busy':'Már folyamatban van egy olvasás.','timeout':'Az olvasás nem fejeződött be időben. Újrapróbálható.'};
  function refresh(automatic=false){
    if(refreshState.state==='loading'||automatic&&Date.now()-lastAttempt<30000)return;
    lastAttempt=Date.now();const requestId=crypto.randomUUID();refreshState={requestId,state:'loading',code:''};notify(false);
    clearTimeout(timeout);timeout=setTimeout(()=>{if(refreshState.requestId===requestId&&refreshState.state==='loading'){refreshState={requestId,state:'error',code:'timeout'};notify(false);}},15000);
    window.postMessage({source:'ss-equipment-read-v1',action:'character',requestId},location.origin);
  }
  window.addEventListener('message',event=>{
    if(event.source!==window||event.origin!==location.origin||event.data?.source!=='ss-statcap-api-v2')return;
    if(event.data.kind==='equipment-character'){snapshot=event.data.payload;const d=M.diagnostics(snapshot,config);if(d.canSave)lastSuccess=snapshot.observedAt;notify();}
    if(event.data.kind==='equipment-refresh'&&event.data.payload?.requestId===refreshState.requestId){const p=event.data.payload;if(['loading','done','error'].includes(p.state)){refreshState={requestId:p.requestId,state:p.state,code:refreshLabels[p.code]?p.code:''};if(p.state!=='loading')clearTimeout(timeout);notify(false);}} 
    if(event.data.kind==='equipment-config'){const next=event.data.payload?.config;config=event.data.payload?.ok&&next?.gameVersion===globalThis.STONESTORM_EQUIPMENT_DATA?.source.gameVersion?next:null;configError=event.data.payload?.error??'Új vagy nem igazolt játékmodell; előbb addonfrissítés szükséges.';notify();}
  });
  function ready(mode='analysis'){const d=M.diagnostics(snapshot,config);if(mode==='save'?!d.canSave:!d.canOptimize)throw Error(mode==='save'?d.saveReason:d.optimizeReason);return snapshot;}
  const itemText=(id,s=snapshot)=>{const i=s?.items.find(x=>x.id===id);return i?(labels[i.templateId]??i.templateId)+' +'+(i.plus??'?')+' · #'+String(i.id).slice(-8):id===null?'Üres slot':'Hiányzó példány';};
  const pct=x=>x===null?'Nem számítható':new Intl.NumberFormat('hu-HU',{maximumFractionDigits:3}).format(x*100)+'%';
  const number=x=>x===null?'Nem számítható':new Intl.NumberFormat('hu-HU',{maximumFractionDigits:2}).format(x);
  globalThis.StonestormEquipmentUI={attach(shadow){
    let panel=null,details=null,body=null,store=null,owner=null,open=false,preview=null,busy=false,abort=null,message='',confirmation=null,lastMock=null,drafts={};
    const runner=T.controller();
    const style=document.createElement('style');style.textContent=`
      [data-equipment-presets]{border-block:1px solid #84653d;background:#151b21;color:#eee1c5}[data-equipment-presets]>summary{padding:12px 16px;cursor:pointer;color:#efcd86;font-weight:750}
      .ssa-equipment-body{padding:12px;font:14px/1.5 system-ui;overflow-wrap:anywhere}.ssa-equipment-body p{margin:7px 0}.ssa-equipment-body button,.ssa-equipment-body input,.ssa-equipment-body select{font:inherit;box-sizing:border-box;max-width:100%;min-width:0;border:1px solid #947243;border-radius:6px;color:#efdfba;background:#282319;padding:8px;min-height:38px}.ssa-equipment-body button:disabled{opacity:.5;cursor:not-allowed}.ssa-equipment-body button:focus-visible,.ssa-equipment-body input:focus-visible{outline:2px solid #edcc80;outline-offset:2px}
      .ssa-presets-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:12px}.ssa-preset{border:1px solid #65543c;border-radius:8px;padding:10px;margin:12px 0;background:#1d2024}.ssa-preset h3{font-size:16px;color:#eed093;margin:0 0 8px}.ssa-preset label{display:block}.ssa-preset input{width:100%;margin-top:5px}.ssa-preset-actions,.ssa-equipment-goals{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.ssa-equipment-warning{padding:10px;border-left:3px solid #c59c55;background:#3a2e2070}.ssa-equipment-message{color:#f3ce89}.ssa-equipment-table{width:100%;border-collapse:collapse;margin:10px 0;font-size:12px}.ssa-equipment-table td,.ssa-equipment-table th{text-align:left;vertical-align:top;padding:6px;border-bottom:1px solid #5c4c39}.ssa-equipment-table th{color:#edce8e}.ssa-equipment-preview{border:1px solid #b58c4a;padding:10px;border-radius:8px;margin-top:14px}.ssa-equipment-confirm{border:2px solid #d9b56b;padding:12px;background:#332a1c;margin-top:12px}.ssa-equipment-note{color:#bdb8a9;font-size:12px}.ssa-equipment-body code{overflow-wrap:anywhere}.ssa-equipment-setlist{padding-left:20px}[data-equipment-diagnostics]{padding:8px;border:1px solid #65543c;margin:8px 0}[data-equipment-diagnostics] dt{font-weight:650;margin-top:6px}[data-equipment-diagnostics] dd{margin:0;color:#c4bdac}
    `;shadow.append(style);
    function cancel(){abort?.abort();confirmation?.(false);confirmation=null;}
    function render(){
      if(!body?.isConnected)return;
      const diagnostic=M.diagnostics(snapshot,config),valid=diagnostic.canSave,canOptimize=diagnostic.canOptimize;
      const status=valid?([snapshot.level&&snapshot.level+'. szint',snapshot.classId,diagnostic.items+' saját tárgy',diagnostic.equipped+' felszerelt'].filter(Boolean).join(' · ')):diagnostic.saveReason;
      const diagnosticOpen=body.querySelector('[data-equipment-diagnostics]')?.open;
      body.innerHTML='<p>'+esc(status)+'</p>'+refreshHTML()+diagnosticHTML(diagnostic)+'<p class="ssa-equipment-warning">A presetmentés és az előnézet csak helyi művelet. A játék felszerelése változatlan marad.</p><p class="ssa-equipment-note">Ebben a helyi kiadásban az éles Felöltözés letiltva. Az előnézet és a mock próba nem módosítja a karaktert. A saját példányazonosítók és presetek csak ezen a gépen maradnak.</p><div class="ssa-presets-grid">'+[0,1,2].map(index=>{const p=store?.presets[index];return '<section class="ssa-preset" data-preset="'+index+'"><h3>'+esc(p?.name??'Preset '+(index+1))+'</h3><label>Preset neve<input data-preset-name="'+index+'" maxlength="40" value="'+esc(drafts[index]??p?.name??'Preset '+(index+1))+'"></label><p class="ssa-equipment-note">'+(p?'Mentett konkrét tárgypéldányok: '+Object.values(p.slots).filter(Boolean).length:'Még nincs mentett felszerelés.')+'</p><div class="ssa-preset-actions">'+[['save','Aktuális felszerelés mentése'],['rename','Átnevezés'],['preview','Preset előnézete'],['delete','Törlés']].map(([action,label])=>'<button type="button" data-preset-action="'+action+'" data-index="'+index+'" '+(!store||busy||(action==='save'||action==='preview')&&!valid||action!=='save'&&!p?'disabled':'')+'>'+label+'</button>').join('')+'<button type="button" disabled title="Először csak mock környezetben ellenőrizhető.">Felöltözés</button></div></section>';}).join('')+'</div><h3>Automatikus szettkereső</h3><div class="ssa-equipment-goals">'+[['xp','XP'],['nyang','Nyang'],['drop','Zsákmány'],['harcero','Harcerő']].map(([goal,label])=>'<button type="button" data-equipment-goal="'+goal+'" '+(!canOptimize||busy||goal==='harcero'?'disabled':'')+'>'+label+'</button>').join('')+'</div><p class="ssa-equipment-note">Teljes kombinációk és aktív szettlépcsők számítása. A Harcerő-keresés a teljes kombinációs modell igazolásáig letiltva. A jelenlegi modellben nincs felszerelési zsákmánybónusz.</p>'+(busy?'<button type="button" data-equipment-cancel>Keresés / próba leállítása</button>':'')+'<p class="ssa-equipment-message" role="status">'+esc(message)+'</p>'+(preview?previewHTML(): '')+(lastMock?.state?'<details><summary>Mock próba: utolsó megfigyelt felszerelés</summary><p>'+esc(lastMock.stateCertain?'Ellenőrzött mock állapot.':'A megkezdett lépés eredménye nem teljesen igazolt; nincs folytatás vagy újrapróbálkozás.')+'</p><ul>'+M.slots.map(sl=>'<li>'+slotNames[sl]+': '+esc(itemText(M.current(lastMock.state)[sl],lastMock.state))+'</li>').join('')+'</ul></details>':'');
      if(diagnosticOpen)body.querySelector('[data-equipment-diagnostics]').open=true;
    }
    function refreshHTML(){return '<button type="button" data-equipment-read '+(refreshState.state==='loading'?'disabled':'')+'>Karakteradatok újraolvasása</button><p class="ssa-equipment-note" data-equipment-read-status role="status">'+esc(refreshState.state==='loading'?'Karakter és inventory olvasása a játék saját GET-kérésével…':refreshState.state==='error'?refreshLabels[refreshState.code]||'Az olvasás nem sikerült.':refreshState.state==='done'?'Az olvasási kérés befejeződött.':'Az újraolvasás nem módosít felszerelést.')+'</p>';}
    function diagnosticHTML(d){return '<details data-equipment-diagnostics><summary>Adatkiolvasási diagnosztika</summary><dl>'+[['Karakteradat megérkezett',d.characterReceived?'igen':'nem'],['Inventoryadat megérkezett',d.inventoryReceived?'igen':'nem'],['Talált tárgyak száma',d.items],['Felszerelt tárgyak száma',d.equipped],['Egyedi ID-val rendelkező tárgyak',d.withUniqueId],['Felismert felszerelési slotok',d.recognizedSlots],['Hiányzó kötelező mezők',d.missing.join(', ')||'nincs'],['Utolsó sikeres frissítés',lastSuccess?new Date(lastSuccess).toLocaleString('hu-HU'):'még nem történt'],['Mentés',d.saveReason],['Optimalizálás',d.optimizeReason],['Felöltözés',d.equipReason],['Harcerő-keresés','A teljes kombinációs Harcerő-képlet nem igazolt, ezért tiltott.']].map(([label,value])=>'<dt>'+esc(label)+'</dt><dd>'+esc(value)+'</dd>').join('')+'</dl></details>';}
    function previewHTML(){
      if(preview.basic)return '<section class="ssa-equipment-preview"><h3>Mentett felszerelés előnézete</h3><p>'+esc(preview.name)+'</p><p>'+esc(preview.note)+'</p><ul>'+M.slots.map(sl=>'<li>'+slotNames[sl]+': '+esc(itemText(preview.gear[sl]))+'</li>').join('')+'</ul><p>A saját tárgypéldányok ellenőrizve. A számított bónuszokhoz további adatok szükségesek; nincs felszerelésváltás.</p></section>';

      const p=preview,before=p.before,after=p.after;
      const metrics=['xp','nyang','drop'].map(k=>'<tr><th>'+({xp:'XP',nyang:'Nyang',drop:'Zsákmány'}[k])+'</th><td>'+pct(before.metrics[k].effective)+'</td><td>'+pct(after.metrics[k].effective)+(after.metrics[k].partial?' · részleges':'')+'</td><td>'+pct(before.metrics[k].effective!==null&&after.metrics[k].effective!==null?after.metrics[k].effective-before.metrics[k].effective:null)+'</td></tr>').join('');
      const setKey=x=>x.id+':'+x.pieces,old=new Set(before.sets.map(setKey)),next=new Set(after.sets.map(setKey)),gains=after.sets.filter(x=>!old.has(setKey(x))),losses=before.sets.filter(x=>!next.has(setKey(x)));
      return '<section class="ssa-equipment-preview"><h3>Jelenlegi felszerelés → Javasolt felszerelés</h3><p>'+esc(p.name)+'</p><p class="ssa-equipment-note">'+esc(p.note)+'</p><table class="ssa-equipment-table"><thead><tr><th>Mutató</th><th>Most</th><th>Javaslat</th><th>Változás</th></tr></thead><tbody>'+metrics+'<tr><th>Harcerő</th><td>'+number(before.metrics.harcero.current)+'</td><td colspan="2">Nem igazolható</td></tr>'+[['maxHp','HP'],['defence','Védelem']].map(([key,label])=>'<tr><th>'+label+'</th><td>'+number(before.metrics[key].value)+'</td><td>'+number(after.metrics[key].value)+'</td><td>Részleges becslés</td></tr>').join('')+'</tbody></table><p>Felszerelés saját XP-bónusza: '+pct(before.total.xp)+' → '+pct(after.total.xp)+'; nyang: '+pct(before.total.nyang)+' → '+pct(after.total.nyang)+'.</p><p>Szettlépcsők: '+(gains.length?'aktiválódik '+gains.map(x=>esc(x.id)+' / '+x.pieces+' db').join(', '):'nincs új')+'; '+(losses.length?'elvész '+losses.map(x=>esc(x.id)+' / '+x.pieces+' db').join(', '):'nincs elvesző')+'.</p><table class="ssa-equipment-table"><thead><tr><th>Slot</th><th>Le</th><th>Fel</th></tr></thead><tbody>'+M.slots.filter(sl=>p.gear[sl]!==p.current[sl]).map(sl=>'<tr><th>'+slotNames[sl]+'</th><td>'+esc(itemText(p.current[sl],p.snapshot))+'</td><td>'+esc(itemText(p.gear[sl],p.snapshot))+'</td></tr>').join('')+'</tbody></table><details><summary>Pontos saját tárgypéldányok</summary><ul>'+M.slots.filter(sl=>p.gear[sl]!==p.current[sl]).map(sl=>'<li>'+slotNames[sl]+': '+esc(p.current[sl]??'üres')+' → '+esc(p.gear[sl]??'üres')+'</li>').join('')+'</ul></details><p>Kézi útmutató: a játék karakterlapján keresd meg a fenti saját tárgypéldányokat, és a játék eredeti felszerelési vezérlőivel cseréld őket. Az addon nem kattint rájuk.</p><label>Javaslat mentése ide<select data-save-target>'+[0,1,2].map(i=>'<option value="'+i+'">'+esc(store?.presets[i]?.name??'Preset '+(i+1))+'</option>').join('')+'</select></label><div class="ssa-preset-actions"><button type="button" data-save-proposal '+(busy?'disabled':'')+'>Javaslat mentése presetként</button><button type="button" data-mock-run '+(busy?'disabled':'')+'>Biztonságos mock próba</button><button type="button" disabled title="Éles felszerelésváltás ebben a kiadásban letiltva.">Felszerelés alkalmazása</button></div><p>Inventory-ellenőrzés: '+esc(p.planError||p.plan?.operations.length+' szükséges művelet; csak mock környezetben.')+'</p></section>';
    }
    function setPreview(gear,label,note){const s=ready(),before=M.evaluate(s,M.current(s),config),after=M.evaluate(s,gear,config);let plan=null,planError='';try{plan=T.plan(s,gear,config);}catch(e){planError=e.message;}preview={gear:M.copy(gear),current:M.current(s),name:label,note,snapshot:M.copy(s),fingerprint:M.fingerprint(s),before,after,plan,planError};}
    async function reload(){
      cancel();preview=null;lastMock=null;store=null;const seq=revision;
      try{const nextOwner=M.key(snapshot?.ownerId);if(owner!==nextOwner)drafts={};owner=nextOwner;const loaded=await S.load(snapshot.ownerId);if(seq!==revision)return;store=loaded;message='';}catch(e){owner=null;message=e.message;}render();
    }
    async function action(button){
      if(busy)return;const kind=button.dataset.presetAction;let s;try{s=['rename','delete'].includes(kind)?snapshot:ready(['save','preview'].includes(kind)?'save':'analysis');if(owner!==M.key(s.ownerId))throw Error('Karakterváltás történt.');}catch(e){message=e.message;render();return;}
      const seq=revision,ownerId=s.ownerId,index=Number(button.dataset.index);
      try{
        if(kind){const label=body.querySelector('[data-preset-name="'+index+'"]').value;
          if(kind==='preview'){const p=store.presets[index],gear=M.presetIdentity(p,s);if(M.diagnostics(s,config).canOptimize)setPreview(gear,p.name,'Mentett tárgypéldányok újraellenőrzött előnézete.');else preview={basic:true,gear,name:p.name,note:M.diagnostics(s,config).optimizeReason};render();return;}
          const value=kind==='save'?M.presetCurrent(s,label):null;
          const result=await S.change(ownerId,prior=>kind==='rename'?M.renamePreset(prior,ownerId,index,label):M.updatePreset(prior,ownerId,index,value));if(seq!==revision)return;store=result;delete drafts[index];message=kind==='delete'?'Preset törölve. A játék tárgyai változatlanok.':'Preset helyben mentve.';
        }else if(button.dataset.equipmentGoal){busy=true;abort=new AbortController();message='Teljes kombinációk keresése…';render();const goal=button.dataset.equipmentGoal,result=await M.optimize(M.copy(s),config,goal,{signal:abort.signal});if(seq!==revision)return;setPreview(result.gear,({xp:'XP',nyang:'Nyang',drop:'Zsákmány'}[goal])+' javaslat',result.reason+(result.partial?' Az érvényes teljes bónusz nem igazolható; felszerelési részmaximum.':''));message=result.nodes+' vizsgált keresési csomópont.';
        }else if(button.hasAttribute('data-save-proposal')){if(!preview||M.fingerprint(s)!==preview.fingerprint)throw Error('Megváltozott állapot; készíts új előnézetet.');const target=Number(body.querySelector('[data-save-target]').value),p=M.preset(s,preview.gear,config,store.presets[target]?.name??preview.name);const result=await S.change(ownerId,prior=>M.updatePreset(prior,ownerId,target,p));if(seq!==revision)return;store=result;message='Javaslat helyben mentve. Nem történt felszereléscsere.';
        }else if(button.hasAttribute('data-mock-run')){if(!preview||M.fingerprint(s)!==preview.fingerprint)throw Error('Megváltozott állapot; készíts új előnézetet.');if(preview.planError)throw Error(preview.planError);busy=true;abort=new AbortController();render();const adapter=T.createMockAdapter(s,config),p=M.preset(s,preview.gear,config,preview.name);const result=await runner.run({adapter,preset:p,config,signal:abort.signal,confirm:plan=>new Promise(resolve=>{confirmation=resolve;const box=document.createElement('section');box.className='ssa-equipment-confirm';box.setAttribute('role','alertdialog');box.setAttribute('aria-label','Mock felszereléscsere megerősítése');box.innerHTML='<p><strong>Csak helyi másolaton futó próba.</strong> '+plan.operations.length+' equip/unequip lépés, a fenti le/fel listával. A valódi karakter változatlan.</p><button type="button" data-confirm-mock>Mock próba megerősítése</button><button type="button" data-cancel-mock>Mégse</button>';body.append(box);box.querySelector('[data-confirm-mock]').onclick=()=>{confirmation=null;box.remove();resolve(true);};box.querySelector('[data-cancel-mock]').onclick=()=>{confirmation=null;box.remove();resolve(false);};box.querySelector('button').focus();})});if(seq!==revision)return;lastMock=result;message=result.status==='completed'?'Mock próba sikeres: '+result.completed.length+' ellenőrzött lépés. A valódi karakter változatlan.':result.status==='cancelled'?'Mock próba visszavonva.':'Mock próba leállt: '+result.error+' · '+result.completed.length+' igazolt lépés. A tényleges mock állapot megőrizve.';
        }
      }catch(e){if(seq===revision)message=e.message;}finally{busy=false;render();}
    }
    function mount(){
      const next=shadow.querySelector('.panel');if(next===panel)return;cancel();panel=next;details=null;body=null;if(!panel)return;
      details=document.createElement('details');details.dataset.equipmentPresets='';details.open=open;const summary=document.createElement('summary');summary.textContent='Felszerelés-presetek és szettkereső';body=document.createElement('div');body.className='ssa-equipment-body';details.append(summary,body);panel.insertBefore(details,panel.querySelector('.panel-content'));
      details.addEventListener('input',e=>{const index=e.target.dataset.presetName;if(['0','1','2'].includes(index))drafts[index]=e.target.value.slice(0,40);});
      details.addEventListener('toggle',()=>{open=details.open;if(!open)cancel();else if(!M.diagnostics(snapshot,config).canSave||!M.diagnostics(snapshot,config).canOptimize)refresh(true);});details.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;e.stopPropagation();if(button.hasAttribute('data-equipment-read')){refresh();return;}if(button.hasAttribute('data-equipment-cancel')){cancel();return;}if(button.disabled||button.hasAttribute('data-confirm-mock')||button.hasAttribute('data-cancel-mock'))return;void action(button);});render();
    }
    subscribers.add(changed=>changed?void reload():render());new MutationObserver(mount).observe(shadow,{subtree:true,childList:true});mount();void reload();
  }};
  window.postMessage({source:'ss-statcap-ready-v2'},location.origin);
})();
